 static class ModernBootstrap {
  public static int Run(string[] args){try{bool trusted=typeof(ModernBootstrap).Assembly.GetManifestResourceInfo("Launcher.UpdatePublicKey.xml")!=null;if(trusted){if(args.Length>0&&args[0]=="--core-update-health")new CoreHealthStartup(args);else{string root=AppDomain.CurrentDomain.BaseDirectory;CoreDeployment.AdoptPortable(root);if(CoreUpdaterProgram.HandoffRecovery(root,CoreUpdateTrust.PublicKeyXml))return 0;}}string assets=ModernAssets.Prepare();return Start(assets,args);}catch(Exception e){if(args.Length>1&&args[0]=="--modern-preview"){File.WriteAllText(args[1]+".error.txt",e.ToString());return 1;}MessageBox.Show("界面启动失败："+e.Message+"\n\n请确认微软 WebView2 Runtime 已安装。官方地址：https://developer.microsoft.com/microsoft-edge/webview2/\n未修改游戏安装或配置。","OZL",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
  [MethodImpl(MethodImplOptions.NoInlining)]static int Start(string assets,string[] args){using(var form=new ModernForm(assets,args)){Application.Run(form);return form.ExitCode;}}
 }
 sealed class ModernForm:Form {
  readonly string assets;readonly string[] args;readonly CoreUpdateService coreUpdate;readonly CoreHealthStartup health;bool restartClosing,closeApproved;readonly WebView2 web;readonly ModernController controller;readonly ModernDispatchQueue dispatcher=new ModernDispatchQueue();readonly bool capture,liveRead;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=2097152,RecursionLimit=40};bool closing;public int ExitCode;
  static string Option(string[] args,string name,string fallback){int i=Array.IndexOf(args,name);return i>=0&&i+1<args.Length?args[i+1]:fallback;}
  public ModernForm(string assets,string[] args):this(assets,args,null,null){}
  internal ModernForm(string assets,string[] args,ModernController selected,CoreUpdateService updates){this.assets=assets;this.args=args;coreUpdate=updates??new CoreUpdateService(AppDomain.CurrentDomain.BaseDirectory);if(args.Length>0&&args[0]=="--core-update-health")health=new CoreHealthStartup(args);coreUpdate.Progress=value=>{if(!IsDisposed&&IsHandleCreated)BeginInvoke(new Action(()=>Post(new{@event="coreUpdateProgress",data=value})));};capture=args.Length>1&&args[0]=="--modern-preview";liveRead=capture&&args.Contains("--live-read");Text="OZL";ClientSize=new Size(1180,780);MinimumSize=new Size(820,600);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(23,27,33);AutoScaleMode=AutoScaleMode.Dpi;
   string dimensions=Option(args,"--size","1180x780");var pieces=dimensions.Split('x');int width,height;if(pieces.Length==2&&int.TryParse(pieces[0],out width)&&int.TryParse(pieces[1],out height)&&width>=780&&height>=560)ClientSize=new Size(width,height);
   if(!capture&&!args.Contains("--size")){using(var graphics=CreateGraphics()){float scale=graphics.DpiX/96f;var area=Screen.FromControl(this).WorkingArea;ClientSize=new Size(Math.Min((int)(1180*scale),area.Width-80),Math.Min((int)(780*scale),area.Height-100));}}
   try{Icon=Icon.ExtractAssociatedIcon(System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName);}catch{}
   if(selected!=null)controller=selected;else{string data=capture?Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"OrangeLauncherRuntime","PreviewData"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PZ3DManager"),user=capture?Path.Combine(data,"user"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Zomboid"),game=capture?Path.Combine(data,"game"):GameDiscovery.Find(GameDiscovery.SteamRoots());string saved=Path.Combine(data,"game-path.txt");if(File.Exists(saved)&&GameDiscovery.IsGameFolder(File.ReadAllText(saved).Trim()))game=File.ReadAllText(saved).Trim();
   if(!capture)LauncherDiagnostics.Install(data);controller=new ModernController(game,user,data,capture&&!liveRead);}if(!capture)controller.RecoverStartup();controller.Progress=(value,text)=>{if(IsDisposed||!IsHandleCreated)return;BeginInvoke(new Action(()=>Post(new{ @event="progress",data=new{value=value,text=text}})));};
   controller.Event=(name,dataValue)=>{if(IsDisposed||!IsHandleCreated)return;BeginInvoke(new Action(()=>Post(new{@event=name,data=dataValue})));};
   web=new WebView2{Dock=DockStyle.Fill,DefaultBackgroundColor=BackColor};Controls.Add(web);Shown+=async(sender,e)=>await Initialize();FormClosing+=HandleClosing;FormClosed+=(sender,e)=>{coreUpdate.Dispose();controller.Dispose();web.Dispose();};
   if(capture){ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Location=new Point(-25000,-25000);}
  }
  async Task Initialize(){try{CoreWebView2Environment.SetLoaderDllFolderPath(assets);string profile=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"OrangeLauncherRuntime",capture?"preview-profile":"browser-profile");LauncherMaintenance.NoReparse(profile);var environment=await CoreWebView2Environment.CreateAsync(null,profile);await web.EnsureCoreWebView2Async(environment);web.CoreWebView2.Settings.AreDevToolsEnabled=false;web.CoreWebView2.Settings.AreDefaultContextMenusEnabled=false;web.CoreWebView2.Settings.IsWebMessageEnabled=true;web.CoreWebView2.Settings.AreHostObjectsAllowed=false;web.CoreWebView2.SetVirtualHostNameToFolderMapping("orange.local",assets,CoreWebView2HostResourceAccessKind.DenyCors);web.CoreWebView2.NavigationStarting+=(sender,e)=>{Uri uri;if(!Uri.TryCreate(e.Uri,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="orange.local"||!uri.IsDefaultPort||uri.AbsolutePath!="/index.html")e.Cancel=true;};web.CoreWebView2.NewWindowRequested+=(sender,e)=>e.Handled=true;web.CoreWebView2.PermissionRequested+=(sender,e)=>e.State=CoreWebView2PermissionState.Deny;web.CoreWebView2.WebMessageReceived+=Message;
    web.CoreWebView2.AddWebResourceRequestedFilter("*",CoreWebView2WebResourceContext.All);web.CoreWebView2.WebResourceRequested+=(sender,e)=>{Uri resource;if(!Uri.TryCreate(e.Request.Uri,UriKind.Absolute,out resource)||resource.Scheme!="https"||resource.Host!="orange.local"||!resource.IsDefaultPort)e.Response=environment.CreateWebResourceResponse(new MemoryStream(),403,"Local UI only","Content-Type: text/plain");};
    double zoom; if(double.TryParse(Option(args,"--zoom","1"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out zoom)&&zoom>=.5&&zoom<=2)web.ZoomFactor=zoom;
    string route=Option(args,"--page","home"),theme=Option(args,"--theme","");if(!new[]{"home","components","shaders","settings","memory","maintenance","help","saves","servers","mods","workshop"}.Contains(route))route="home";
    web.CoreWebView2.NavigationCompleted+=async(sender,e)=>{if(!e.IsSuccess&&health!=null){ExitCode=1;Close();return;}if(e.IsSuccess&&health!=null)try{health.PageLoaded();}catch{ExitCode=1;Close();return;}if(!capture)return;if(!e.IsSuccess){ExitCode=1;Close();return;}try{await Task.Delay(1800);if(liveRead){DateTime readyDeadline=DateTime.UtcNow.AddSeconds(15);while(await web.CoreWebView2.ExecuteScriptAsync("Boolean(window.orange?.state?.status)")!="true"){if(DateTime.UtcNow>readyDeadline)throw new Exception("真实状态尚未读取完成，拒绝把占位页当作验证截图。");await Task.Delay(100);}}if(args.Contains("--java-panel")){await web.CoreWebView2.ExecuteScriptAsync("document.querySelector(\'[data-java-open]\')?.click()");await Task.Delay(700);}if(args.Contains("--save-detail")){await web.CoreWebView2.ExecuteScriptAsync("document.querySelector(\'[data-save-open]\')?.click()");await Task.Delay(1300);}string ready=await web.CoreWebView2.ExecuteScriptAsync("document.readyState");if(ready!="\"complete\"")await Task.Delay(1000);string output=Path.GetFullPath(args[1]);LauncherMaintenance.NoReparse(output);Directory.CreateDirectory(Path.GetDirectoryName(output));using(var stream=File.Create(output))await web.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);ExitCode=0;}catch(Exception error){ExitCode=1;File.WriteAllText(args[1]+".error.txt",error.ToString());}finally{Close();}};
    web.CoreWebView2.Navigate("https://orange.local/index.html?"+(capture&&!liveRead?"preview=1&":"")+"page="+Uri.EscapeDataString(route)+"&theme="+Uri.EscapeDataString(theme));
   }catch(Exception error){ExitCode=1;if(capture){File.WriteAllText(args[1]+".error.txt",error.ToString());Close();}else{MessageBox.Show(this,"界面运行库启动失败："+error.Message+"\n请安装微软官方 WebView2 Runtime 后重试；未修改游戏。","界面启动失败",MessageBoxButtons.OK,MessageBoxIcon.Error);Close();}}
  }
  async void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){string id="";try{var request=ModernHostPolicy.Validate(e.Source,e.WebMessageAsJson);id=(string)request["id"];string action=(string)request["action"];var payload=(Dictionary<string,object>)request["payload"];if(typeof(ModernForm).Assembly.GetManifestResourceInfo("Launcher.UpdatePublicKey.xml")!=null){object protocol;if(!request.TryGetValue("protocol",out protocol)||!(protocol is int)||(int)protocol!=1)throw new Exception("页面与启动器核心不兼容，请重新安装完整版本。");}if(health!=null)health.AssertAction(action);if(CoreAction(request,action,payload)){if(health!=null)health.BridgeReady();return;}if(dispatcher.RestartReserved)throw new Exception("正在准备重启，请稍候。");if(capture&&(!liveRead||!ModernController.NativeReads.Contains(action)))throw new Exception("界面截图模式不执行任何真实修改。");if(action=="chooseGame"){if(controller.Busy)throw new Exception("任务进行中，不能切换安装目录。");using(var picker=new FolderBrowserDialog{Description="选择包含 ProjectZomboid64.exe 与 JSON 的游戏目录"}){if(picker.ShowDialog(this)!=DialogResult.OK){Post(new{id=id,ok=true,data=new{cancelled=true}});return;}action="setGame";payload=new Dictionary<string,object>{{"path",picker.SelectedPath}};}}else if(action=="importShader"){if(controller.Busy)throw new Exception("任务进行中，不能导入光影。");using(var picker=new OpenFileDialog{Title="选择光影 ZIP",Filter="光影包 ZIP|*.zip"}){if(picker.ShowDialog(this)!=DialogResult.OK){Post(new{id=id,ok=true,data=new{cancelled=true}});return;}payload=new Dictionary<string,object>{{"path",picker.FileName}};}}
if(action=="serverHall")controller.ReserveHall(payload);
object result=await (action=="taskGet"||action=="playtimeGet"||action=="serverWorkshopStatus"||action=="serverWorkshopCancel"||ModernController.NativeNetworkReads.Contains(action)||ModernController.IsHallCancel(action,payload)?dispatcher.ExecuteSnapshot(()=>controller.Execute(action,payload)):action=="cancel"||ModernController.NativeReads.Contains(action)?dispatcher.Execute(()=>controller.Execute(action,payload),action=="cancel"):dispatcher.ExecuteMutation(()=>controller.Execute(action,payload)));if(liveRead&&action=="status"){string requested=Option(args,"--theme","");if(requested=="dark"||requested=="light"){var copy=json.Deserialize<Dictionary<string,object>>(json.Serialize(result));copy["theme"]=requested;result=copy;}}Post(new{id=id,ok=true,data=result});if(health!=null&&action=="status")health.BridgeReady();
   }catch(Exception error){Post(new{id=id,ok=false,error=error.Message});}finally{if(closing&&!controller.Busy)Close();}}
  async void HandleClosing(object sender,FormClosingEventArgs e){if(capture||restartClosing||closeApproved)return;e.Cancel=true;if(controller.Busy){closing=true;controller.Cancel();Post(new{@event="progress",data=new{value=-1,text="正在安全取消任务，结束后关闭窗口"}});return;}if(web.CoreWebView2!=null){try{string dirty=await web.CoreWebView2.ExecuteScriptAsync("Boolean(window.orange?.hasUnsavedDrafts?.())");if(dirty=="true"&&MessageBox.Show(this,"存在未保存编辑，关闭会丢失草稿。仍要退出？","未保存编辑",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning)!=DialogResult.OK)return;}catch{return;}}closeApproved=true;Close();}
  bool CoreAction(Dictionary<string,object> request,string action,Dictionary<string,object> payload){if(!ModernHostPolicy.CoreAction(action))return false;string id=(string)request["id"];if(capture&&action!="coreUpdateStatus")throw new Exception("截图模式不执行更新操作。");if(action=="coreUpdatePreflight"){Post(new{id=id,ok=true,data=ModernHostPolicy.CorePreflight(controller,dispatcher,capture)});return true;}if(action=="coreUpdateApply"){ApplyCore(id);return true;}CoreUpdateStatus result=action=="coreUpdateCheck"?coreUpdate.Check():action=="coreUpdateDownload"?coreUpdate.Download():action=="coreUpdateCancel"?coreUpdate.Cancel():coreUpdate.Status();Post(new{id=id,ok=true,data=result});return true;}
  async void ApplyCore(string id){bool reserved=false;try{if(capture)throw new Exception("截图模式不执行更新。");if(!dispatcher.TryReserveRestart())throw new Exception("存在排队或执行中的修改，请完成后重试。");reserved=true;if(await web.CoreWebView2.ExecuteScriptAsync("Boolean(window.orange?.hasUnsavedDrafts?.())")!="false")throw new Exception("请先保存或放弃未保存的编辑。");controller.Cancel();await dispatcher.Drain();controller.AssertCanRestart();string task=coreUpdate.PreparedTask();using(var original=System.Diagnostics.Process.GetCurrentProcess())using(var helper=await Task.Run(()=>CoreUpdaterProgram.Start(AppDomain.CurrentDomain.BaseDirectory,task,original,CoreUpdateTrust.PublicKeyXml))){try{controller.AssertCanRestart();if(await web.CoreWebView2.ExecuteScriptAsync("Boolean(window.orange?.hasUnsavedDrafts?.())")!="false")throw new Exception("准备期间产生了未保存编辑，请先保存。");coreUpdate.HandoffStarted();Post(new{id=id,ok=true,data=coreUpdate.Status()});restartClosing=true;Close();}catch{if(!helper.HasExited){helper.Kill();helper.WaitForExit(5000);}throw;}}}
   catch(Exception error){if(reserved)dispatcher.ReleaseRestart();Post(new{id=id,ok=false,error=error.Message});}}
